// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // The fuzz parameter is an address for _accessControl. The general rule:
    // After any successful call to initialize(_accessControl), the Initializable storage's _initialized
    // should be set to 1; we observe this by calling initialize twice and expecting the second call to revert
    // (initializer prevents re-initialization). The buggy mutant omitting __UUPSUpgradeable_init()
    // will allow re-initialization in some contexts, so the second initialize may succeed for some inputs.
    function testFuzz_property(address accessControl) public {
        // keep domain wide but avoid zero address to be realistic (still wide).
        if (accessControl == address(0)) accessControl = address(1);

        bool firstOk;
        try c.initialize(accessControl) {
            firstOk = true;
        } catch {
            firstOk = false;
        }

        // If first initialization reverted, nothing more to check; property concerns successful initialize behavior.
        vm.assume(firstOk == true);

        // Try to initialize a second time with same parameter. Correct contract should revert (initializer prevents re-entry),
        // so secondOk should be false. The mutant (missing __UUPSUpgradeable_init) can cause different initialized flag
        // behavior and may allow second initialize to succeed for some inputs; thus assert that second call fails.
        bool secondOk;
        try c.initialize(accessControl) {
            secondOk = true;
        } catch {
            secondOk = false;
        }

        // Single assertion: reference contract always makes secondOk == false for all inputs; the mutant will make it true for some.
        assertTrue(secondOk == false);
    }
}

